SELECT mr.message_id, c.id, c.link_id, c.email_address, COALESCE(mr.name, c.name) as "name", -- name from message overrides contact name c.original_photo_url, c.sfs_photo_url, c.created_at, c.updated_at, mr.recipient_type as "recipient_type!: db::address::EmailRecipientType" FROM email_messages m JOIN email_message_recipients mr ON m.id = mr.message_id JOIN email_contacts c ON mr.contact_id = c.id WHERE m.id = ANY($1) ORDER BY mr.message_id, mr.recipient_type
